type StrictOperationInput<TKey extends OperationId> = TKey extends keyof IdentityOperationInputs
  ? IdentityOperationInputs[TKey]
  : SchemaOutput<(typeof OPERATION_SCHEMAS)[TKey]['input']>;
export type OperationInputFor<TKey extends OperationId> = StrictOperationInput<TKey>;
export type OperationOutputFor<TKey extends OperationId> = SchemaOutput<(typeof OPERATION_SCHEMAS)[TKey]['output']>;

export function operationSchema<TKey extends OperationId>(id: TKey): (typeof OPERATION_SCHEMAS)[TKey] { return OPERATION_SCHEMAS[id]; }
